template <typename T>
constexpr T CompileTimeMax(T a, T b) {
    return (a > b) ? a : b;
}

constexpr int CTM_Value = CompileTimeMax(10, 20); // Computed at compile time

template <typename T>
auto Dispatch(T value) {
    if constexpr (std::is_pointer_v<T>) {
        return *value; // Only compiled if T is a pointer
    } else if constexpr (std::is_integral_v<T>) {
        return value + 1;
    } else {
        static_assert(false, "Unsupported type."); // Compile-time error
    }
}

template<int N>
struct Fib {
    static constexpr int value = Fib<N-1>::value + Fib<N-2>::value;
};
template<> struct Fib<0> { static constexpr int value = 0; };
template<> struct Fib<1> { static constexpr int value = 1; };

constexpr int F8 = Fib<8>::value; // TMP Result: 21
